struct Point {
  int16_t x;
  int16_t y;
};

struct SensorReading {
  Point location;
  float celsius;
  bool valid;
  bool isHot(float limit) const { return valid && celsius > limit; }
};

class Threshold {
 public:
  explicit Threshold(float limit) : limit_(limit) {}
  bool exceeded(float value) const { return value > limit_; }
 private:
  float limit_;
};

SensorReading readings[2] = {{{1, 2}, 24.5f, true},
                             {{3, 4}, 0.0f, false}};
